// Measured sensor shift — from metrics.json via MODEL_PARAMS, with the exact
// metrics.json definition as fallback (zero months counted on BOTH sides).
const SENSOR_SHIFT = (typeof MODEL_PARAMS !== 'undefined' && MODEL_PARAMS.stepRatio != null)
  ? MODEL_PARAMS.stepRatio
  : (() => {
      const pre = CHT_SERIES.filter(d => d.y < 2012 && d.modis != null);
      const post = CHT_SERIES.filter(d => d.y >= 2012 && d.viirs != null);
      if (!pre.length || !post.length) return null;
      const mean = a => a.reduce((s, v) => s + v, 0) / a.length;
      const preMean = mean(pre.map(d => d.modis));
      return preMean > 0 ? mean(post.map(d => d.viirs)) / preMean : null;
    })();

const SENSOR_SHIFT_LABEL = SENSOR_SHIFT == null
  ? 'Sensor Shift Jump'
  : `Artificial +${Math.round((SENSOR_SHIFT - 1) * 100)}% Sensor Inflation (${SENSOR_SHIFT.toFixed(2)}×)`;

